 25→// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
 26→// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
 27→// no "has unpushed" optimization — we always attempt the push and let git handle
 28→// the no-op case.
 29→func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 30→	repo, err := OpenRepository(ctx)
 31→	if err != nil {
 32→		return nil //nolint:nilerr // Hook must be silent on failure
 33→	}
 34→
 35→	if _, err := repo.Reference(refName, true); err != nil {
 36→		return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
 37→	}
 38→
 39→	return doPushRef(ctx, target, refName)
 40→}
 41→
 42→// tryPushRef attempts to push a custom ref using an explicit refspec.
 43→func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 44→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
 45→	defer cancel()
 46→
 47→	// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
 48→	refSpec := fmt.Sprintf("%s:%s", refName, refName)
 49→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", target, refSpec)
 50→	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
 51→
 52→	output, err := cmd.CombinedOutput()
 53→	if err != nil {
 54→		if strings.Contains(string(output), "non-fast-forward") ||
 55→			strings.Contains(string(output), "rejected") {
 56→			return errors.New("non-fast-forward")
 57→		}
 58→		return fmt.Errorf("push failed: %s", output)
 59→	}
 60→	return nil
 61→}
 62→
 63→// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
 64→func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 65→	displayTarget := target
 66→	if isURL(target) {
 67→		displayTarget = "checkpoint remote"
 68→	}
 69→
 70→	shortRef := shortRefName(refName)
 71→	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
 72→	stop := startProgressDots(os.Stderr)
 73→
 74→	if err := tryPushRef(ctx, target, refName); err == nil {
 75→		stop(" done")
 76→		return nil
 77→	}
 78→	stop("")
 79→
 80→	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
 81→	stop = startProgressDots(os.Stderr)
 82→
 83→	if err := fetchAndMergeRef(ctx, target, refName); err != nil {
 84→		stop("")
 85→		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
 86→		printCheckpointRemoteHint(target)
 87→		return nil
 88→	}
 89→	stop(" done")
 90→
 91→	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
 92→	stop = startProgressDots(os.Stderr)
 93→
 94→	if err := tryPushRef(ctx, target, refName); err != nil {
 95→		stop("")
 96→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
 97→		printCheckpointRemoteHint(target)
 98→	} else {
 99→		stop(" done")
100→	}
101→
102→	return nil
103→}
