199→// detectRemoteOnlyArchives discovers archived generation refs on the remote
200→// that don't exist locally. Returns them sorted ascending (oldest first).
201→func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
202→	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
203→	defer cancel()
204→
205→	cmd := exec.CommandContext(ctx, "git", "ls-remote", target, paths.V2FullRefPrefix+"*")
206→	output, err := cmd.Output()
207→	if err != nil {
208→		return nil, fmt.Errorf("ls-remote failed: %w", err)
209→	}
210→
211→	var remoteOnly []string
212→	for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
213→		if line == "" {
214→			continue
215→		}
216→		parts := strings.Fields(line)
217→		if len(parts) < 2 {
218→			continue
219→		}
220→		refName := parts[1]
221→		suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
222→		if suffix == "current" || !generationRefPattern.MatchString(suffix) {
223→			continue
224→		}
225→		// Only check for existence, not hash equality. A locally-present archive
226→		// could be stale if another machine updated it via rotation conflict recovery,
227→		// but that's unlikely and the checkpoints are still on /main regardless.
228→		if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
229→			remoteOnly = append(remoteOnly, suffix)
230→		}
231→	}
232→
233→	sort.Strings(remoteOnly)
234→	return remoteOnly, nil
235→}
