237→// handleRotationConflict handles the case where remote /full/current was rotated.
238→// Merges local /full/current into the latest remote archived generation to avoid
239→// duplicating checkpoint data, then adopts remote's /full/current as local.
240→func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
241→	// Use the latest remote-only archive
242→	latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
243→	archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
244→
245→	// Fetch the latest archived generation
246→	archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
247→	archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
248→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", target, archiveRefSpec)
249→	if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
250→		return fmt.Errorf("fetch archived generation failed: %s", output)
251→	}
252→	defer func() {
253→		_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
254→	}()
255→
256→	// Get archived generation state
257→	archiveRef, err := repo.Reference(archiveTmpRef, true)
258→	if err != nil {
259→		return fmt.Errorf("failed to get archived ref: %w", err)
260→	}
261→	archiveCommit, err := repo.CommitObject(archiveRef.Hash())
262→	if err != nil {
263→		return fmt.Errorf("failed to get archive commit: %w", err)
264→	}
265→	archiveTree, err := archiveCommit.Tree()
266→	if err != nil {
267→		return fmt.Errorf("failed to get archive tree: %w", err)
268→	}
269→
270→	// Get local /full/current state
271→	localRef, err := repo.Reference(refName, true)
272→	if err != nil {
273→		return fmt.Errorf("failed to get local ref: %w", err)
274→	}
275→	localCommit, err := repo.CommitObject(localRef.Hash())
276→	if err != nil {
277→		return fmt.Errorf("failed to get local commit: %w", err)
278→	}
279→	localTree, err := localCommit.Tree()
280→	if err != nil {
281→		return fmt.Errorf("failed to get local tree: %w", err)
282→	}
283→
284→	// Tree-merge local /full/current into archived generation.
285→	// Git content-addressing deduplicates shared shard paths automatically.
286→	entries := make(map[string]object.TreeEntry)
287→	if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
288→		return fmt.Errorf("failed to flatten archive tree: %w", err)
289→	}
290→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
291→		return fmt.Errorf("failed to flatten local tree: %w", err)
292→	}
293→
294→	// Update generation.json timestamps if present in the merged tree.
295→	// Use the local /full/current HEAD commit time as the newest checkpoint time
296→	// (more accurate than time.Now() for cleanup scheduling).
297→	if genEntry, exists := entries[paths.GenerationFileName]; exists {
298→		if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
299→			entries[paths.GenerationFileName] = updatedEntry
300→		}
301→	}
302→
303→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
304→	if err != nil {
305→		return fmt.Errorf("failed to build merged tree: %w", err)
306→	}
307→
308→	// Create commit parented on archive's commit (fast-forward)
309→	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
310→		[]plumbing.Hash{archiveRef.Hash()},
311→		"Merge local checkpoints into archived generation")
312→	if err != nil {
313→		return fmt.Errorf("failed to create merge commit: %w", err)
314→	}
315→
316→	// Update local archived ref and push it
317→	newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
318→	if err := repo.Storer.SetReference(newArchiveRef); err != nil {
319→		return fmt.Errorf("failed to update archive ref: %w", err)
320→	}
321→
322→	if pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
323→		return fmt.Errorf("failed to push updated archive: %w", pushErr)
324→	}
325→
326→	// Adopt remote's /full/current as local
327→	remoteRef, err := repo.Reference(tmpRefName, true)
328→	if err != nil {
329→		return fmt.Errorf("failed to get fetched /full/current: %w", err)
330→	}
331→	adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
332→	if err := repo.Storer.SetReference(adoptedRef); err != nil {
333→		return fmt.Errorf("failed to adopt remote /full/current: %w", err)
334→	}
335→
336→	return nil
337→}
