339→// updateGenerationTimestamps reads generation.json from a blob, updates
340→// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
341→// an updated tree entry. Uses the local commit timestamp rather than
342→// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
343→func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
344→	blob, err := repo.BlobObject(genBlobHash)
345→	if err != nil {
346→		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
347→	}
348→	reader, err := blob.Reader()
349→	if err != nil {
350→		return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
351→	}
352→	defer reader.Close()
353→
354→	data, err := io.ReadAll(reader)
355→	if err != nil {
356→		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
357→	}
358→
359→	var gen checkpoint.GenerationMetadata
360→	if err := json.Unmarshal(data, &gen); err != nil {
361→		return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
362→	}
363→
364→	if newestFromLocal.After(gen.NewestCheckpointAt) {
365→		gen.NewestCheckpointAt = newestFromLocal
366→	}
367→
368→	updatedData, err := json.Marshal(gen)
369→	if err != nil {
370→		return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
371→	}
372→
373→	newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
374→	if err != nil {
375→		return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
376→	}
377→
378→	return object.TreeEntry{
379→		Name: paths.GenerationFileName,
380→		Mode: filemode.Regular,
381→		Hash: newBlobHash,
382→	}, nil
383→}
