385→// pushV2Refs pushes v2 checkpoint refs to the target.
386→// Pushes /main, /full/current, and the latest archived generation (if any).
387→// Older archived generations are immutable and were pushed when created.
388→func pushV2Refs(ctx context.Context, target string) {
389→	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
390→	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
391→
392→	// Push only the latest archived generation (most likely to be newly created)
393→	repo, err := OpenRepository(ctx)
394→	if err != nil {
395→		return
396→	}
397→	store := checkpoint.NewV2GitStore(repo)
398→	archived, err := store.ListArchivedGenerations()
